import { NextRequest } from "next/server";
import { z } from "zod";
import { getDb } from "@/lib/db";

export const dynamic = "force-dynamic";

/** Saved chart layouts, so a dashboard survives a browser reset. */

const Body = z.object({
  name: z.string().min(1).max(64),
  layout: z.array(z.unknown()),
});

export async function GET(req: NextRequest) {
  const name = req.nextUrl.searchParams.get("name");
  const db = getDb();

  if (name) {
    const row = db.prepare(`SELECT layout FROM dashboards WHERE name = ?`).get(name) as
      | { layout: string }
      | undefined;
    return Response.json({ layout: row ? JSON.parse(row.layout) : null });
  }

  const rows = db
    .prepare(`SELECT name, updated_at AS updatedAt FROM dashboards ORDER BY updated_at DESC`)
    .all();
  return Response.json({ dashboards: rows });
}

export async function POST(req: NextRequest) {
  let body: z.infer<typeof Body>;
  try {
    body = Body.parse(await req.json());
  } catch {
    return Response.json({ error: "Očekávám { name, layout[] }" }, { status: 400 });
  }

  getDb()
    .prepare(
      `INSERT INTO dashboards (name, layout, updated_at) VALUES (?,?,?)
       ON CONFLICT(name) DO UPDATE SET layout = excluded.layout, updated_at = excluded.updated_at`,
    )
    .run(body.name, JSON.stringify(body.layout), new Date().toISOString());

  return Response.json({ ok: true });
}

export async function DELETE(req: NextRequest) {
  const name = req.nextUrl.searchParams.get("name");
  if (!name) return Response.json({ error: "Chybí ?name=" }, { status: 400 });
  getDb().prepare(`DELETE FROM dashboards WHERE name = ?`).run(name);
  return Response.json({ ok: true });
}
